def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n == 3:
        return 'C'

    opp_def_early = False
    for i in range(3):
        if history[i][1] == 'D':
            opp_def_early = True
            break
    if opp_def_early:
        return 'D'

    if history[3][1] == 'D':
        if n == 99:
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        return 'C'
    if last_my == 'D':
        return 'C'

    recent = history[-10:] if n >= 10 else history
    opp_coop = sum(1 for _, o in recent if o == 'C') / len(recent)
    if opp_coop >= 0.95:
        p = 0.3
    elif opp_coop >= 0.8:
        p = 0.15
    else:
        p = 0.05

    if n >= 95:
        p = 0.6

    if rng.random() < p:
        return 'D'
    return 'C'
